sys_script_client.script:
function onLoad() {
    applySubTemplateStateReadonly();
}

function applySubTemplateStateReadonly() {
    var state = g_form.getValue('state');

    // Fields to lock after Draft
    var setupFields = [
        'table',
        'condition',
        'html_template',
		'evaluate_records_using_script',
        'record_selection_script'
    ];

    // Fields to lock after Validation
    var selectionFields = [
        'empty_message'
    ];

    // First reset everything to editable
    setFieldsReadOnly(setupFields, false);
    setFieldsReadOnly(selectionFields, false);

    // Draft: everything editable
    if (state == 'draft' || state == '') {
        return;
    }

    // Mapping: lock setup fields only
    if (state == 'mapping') {
        setFieldsReadOnly(setupFields, true);
        return;
    }

    // Validated / Complete: lock all controlled fields
    if (state == 'validated' || state == 'complete') {
        setFieldsReadOnly(setupFields, true);
        setFieldsReadOnly(selectionFields, true);
        return;
    }
}

function setFieldsReadOnly(fields, readOnly) {
    for (var i = 0; i < fields.length; i++) {
        g_form.setReadOnly(fields[i], readOnly);
    }
}
